using Khazar.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Khazar.Infrastructure.Persistence.Configurations;

// Storefront content tables. Ids are generated by the domain (BaseEntity), not by the database. JSON columns
// (section data, article body, lookbook hotspots) are nvarchar(max); the application layer validates their shape.

public sealed class ContentSectionConfiguration : IEntityTypeConfiguration<ContentSection>
{
    public const string KeyIndexName = "IX_ContentSections_Key";

    public void Configure(EntityTypeBuilder<ContentSection> builder)
    {
        builder.ToTable("ContentSections");
        builder.HasKey(s => s.Id);
        builder.Property(s => s.Id).ValueGeneratedNever();

        builder.Property(s => s.Key).IsRequired().HasMaxLength(ContentSection.MaxKeyLength);
        builder.Property(s => s.Data).IsRequired();

        builder.HasIndex(s => s.Key).IsUnique().HasDatabaseName(KeyIndexName);
    }
}

public sealed class JournalArticleConfiguration : IEntityTypeConfiguration<JournalArticle>
{
    public const string SlugIndexName = "IX_JournalArticles_Slug";

    public void Configure(EntityTypeBuilder<JournalArticle> builder)
    {
        builder.ToTable("JournalArticles");
        builder.HasKey(a => a.Id);
        builder.Property(a => a.Id).ValueGeneratedNever();

        builder.Property(a => a.Slug).IsRequired().HasMaxLength(JournalArticle.MaxSlugLength);
        builder.Property(a => a.Title).IsRequired().HasMaxLength(JournalArticle.MaxTitleLength);
        builder.Property(a => a.Excerpt).IsRequired().HasMaxLength(JournalArticle.MaxExcerptLength);
        builder.Property(a => a.CoverImageUrl).IsRequired().HasMaxLength(JournalArticle.MaxImageUrlLength);
        builder.Property(a => a.Meta).IsRequired().HasMaxLength(JournalArticle.MaxMetaLength);
        builder.Property(a => a.Body).IsRequired();

        builder.HasIndex(a => a.Slug).IsUnique().HasDatabaseName(SlugIndexName);
        builder.HasIndex(a => new { a.IsPublished, a.SortOrder });
    }
}

public sealed class LookbookLookConfiguration : IEntityTypeConfiguration<LookbookLook>
{
    public void Configure(EntityTypeBuilder<LookbookLook> builder)
    {
        builder.ToTable("LookbookLooks");
        builder.HasKey(l => l.Id);
        builder.Property(l => l.Id).ValueGeneratedNever();

        builder.Property(l => l.Title).IsRequired().HasMaxLength(LookbookLook.MaxTitleLength);
        builder.Property(l => l.ImageUrl).IsRequired().HasMaxLength(LookbookLook.MaxImageUrlLength);
        builder.Property(l => l.CtaLabel).IsRequired().HasMaxLength(LookbookLook.MaxCtaLabelLength);
        builder.Property(l => l.CtaLink).IsRequired().HasMaxLength(LookbookLook.MaxCtaLinkLength);
        builder.Property(l => l.Hotspots).IsRequired();

        builder.HasIndex(l => new { l.IsPublished, l.SortOrder });
    }
}

public sealed class FaqItemConfiguration : IEntityTypeConfiguration<FaqItem>
{
    public void Configure(EntityTypeBuilder<FaqItem> builder)
    {
        builder.ToTable("FaqItems");
        builder.HasKey(f => f.Id);
        builder.Property(f => f.Id).ValueGeneratedNever();

        builder.Property(f => f.Question).IsRequired().HasMaxLength(FaqItem.MaxQuestionLength);
        builder.Property(f => f.Answer).IsRequired().HasMaxLength(FaqItem.MaxAnswerLength);

        builder.HasIndex(f => new { f.IsPublished, f.SortOrder });
    }
}

public sealed class ContactMessageConfiguration : IEntityTypeConfiguration<ContactMessage>
{
    public void Configure(EntityTypeBuilder<ContactMessage> builder)
    {
        builder.ToTable("ContactMessages");
        builder.HasKey(m => m.Id);
        builder.Property(m => m.Id).ValueGeneratedNever();

        builder.Property(m => m.Name).IsRequired().HasMaxLength(ContactMessage.MaxNameLength);
        builder.Property(m => m.Email).IsRequired().HasMaxLength(ContactMessage.MaxEmailLength);
        builder.Property(m => m.Message).IsRequired().HasMaxLength(ContactMessage.MaxMessageLength);
        builder.Ignore(m => m.IsRead);

        builder.HasIndex(m => m.CreatedAt);
    }
}
